begin;
select set_config('test.a',gen_random_uuid()::text,true);
select set_config('test.b',gen_random_uuid()::text,true);
select set_config('test.m',gen_random_uuid()::text,true);
select set_config('test.r',gen_random_uuid()::text,true);
select set_config('test.s',gen_random_uuid()::text,true);
select set_config('test.key',gen_random_uuid()::text,true);
insert into auth.users(id,email) values(current_setting('test.a')::uuid,'TESTE-sales-a@example.invalid'),(current_setting('test.b')::uuid,'TESTE-sales-b@example.invalid');
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('test.a'),true);
select public.initialize_account();
select public.commerce_command(gen_random_uuid(),'fees','update',current_setting('test.a')::uuid,'{"debit_fee_percent":2,"credit_fee_percent":5.49}');
select public.material_command(gen_random_uuid(),'create',current_setting('test.m')::uuid,'{"name":"TESTE Cacau","kind":"ingredient","unit":"kg","package_quantity":1,"package_price_cents":3072}');
select public.recipe_command(gen_random_uuid(),'create',current_setting('test.r')::uuid,jsonb_build_object('name','TESTE Brigadeiro','yield_units',5,'indirect_percent',25,'fee_percent',5.49,'final_quantity',500,'final_unit','g','serving_unit','g','components',jsonb_build_array(jsonb_build_object('material_id',current_setting('test.m'),'quantity',500,'unit','g'))));
select set_config('test.base',jsonb_build_object('recipe_id',current_setting('test.r'),'quantity',1,'unit_price_cents',1000,'payment','credit','occurred_local','2026-10-20T23:59:59','anonymous',false,'customer_name','TESTE Antigo','customer_phone','(11) 99999-9999')::text,true);

do $$ declare d jsonb; q jsonb; s uuid:=current_setting('test.s')::uuid; second_product uuid:=gen_random_uuid(); begin
 d:=current_setting('test.base')::jsonb||'{"anonymous":true}';q:=public.sale_preview(null,d);
 perform public.commerce_command(gen_random_uuid(),'sale','create',s,d||jsonb_build_object('quote_signature',q->>'signature'));
 perform public.material_command(gen_random_uuid(),'update',current_setting('test.m')::uuid,'{"name":"TESTE Cacau","kind":"ingredient","unit":"kg","package_quantity":1,"package_price_cents":1000}');
 perform public.recipe_command(gen_random_uuid(),'create',second_product,jsonb_build_object('name','TESTE Fracionário','yield_units',10,'indirect_percent',25,'fee_percent',0,'final_quantity',500,'final_unit','g','serving_unit','g','components',jsonb_build_array(jsonb_build_object('material_id',current_setting('test.m'),'quantity',500,'unit','g'))));
 perform public.commerce_command(gen_random_uuid(),'fees','update',current_setting('test.a')::uuid,'{"debit_fee_percent":10,"credit_fee_percent":20}');
 d:=d||jsonb_build_object('recipe_id',second_product,'quantity',3,'unit_price_cents',101,'payment','debit');
 begin perform public.sale_preview(s,d);raise exception 'TESTE troca sem confirmação';exception when invalid_parameter_value then null;end;
 d:=d||'{"confirm_product_change":true}';q:=public.sale_preview(s,d);
 if (q->>'unit_cost')::numeric<>0.625 or (q->>'applied_fee_percent')::numeric<>10 or q->>'production_cents'<>'188' or q->>'fee_cents'<>'30' or q->>'gross_cents'<>'303' then raise exception 'TESTE troca/fracionamento %',q;end if;
 perform public.commerce_command(gen_random_uuid(),'sale','update',s,d||jsonb_build_object('quote_signature',q->>'signature'));
 perform public.commerce_command(gen_random_uuid(),'fees','update',current_setting('test.a')::uuid,'{"debit_fee_percent":30,"credit_fee_percent":40}');
 d:=d||'{"payment":"credit","confirm_product_change":false}';q:=public.sale_preview(s,d);
 if q->>'fee_cents'<>'61' or (q->>'applied_fee_percent')::numeric<>20 then raise exception 'TESTE taxa histórica da troca';end if;
 d:=d||'{"unit_price_cents":0,"confirm_loss":true}';q:=public.sale_preview(s,d);
 perform public.commerce_command(gen_random_uuid(),'sale','update',s,d||jsonb_build_object('quote_signature',q->>'signature'));
 if not exists(select 1 from public.sale_catalog where gross_cents='0' and profit_cents='-188' and production_cents='188' and fee_cents='0') then raise exception 'TESTE gratuidade confirmada';end if;
 d:=d||'{"occurred_local":"2099-12-31T23:59:59"}';q:=public.sale_preview(null,d);
 perform public.commerce_command(gen_random_uuid(),'sale','create',gen_random_uuid(),d||jsonb_build_object('quote_signature',q->>'signature'));
 begin perform public.sale_preview(null,d||'{"occurred_local":"2018-11-04T00:30:00"}');raise exception 'TESTE horário inexistente';exception when invalid_parameter_value then null;end;
 begin update public.business_settings set credit_fee_percent=5;raise exception 'TESTE taxa direta fora da revisão';exception when insufficient_privilege then null;end;
end $$;
reset role;rollback;
select 'Troca explícita de produto, taxas históricas após troca, débito, centavos fracionários e gratuidade confirmada: aprovados.' as resultado;
